local rows={}
for _,group in ipairs(groups)do
  for _,cell in ipairs(group.cells)do
    local row={id=cell[1],quadrant=cell[2],sourceCells=cell[3],sourceFiles=files[group.files]}
    for key,value in pairs(group)do
      if key~='files' and key~='art' and key~='cells' then row[key]=value end
    end
    for key,value in pairs(art[group.art])do row[key]=value end
    rows[#rows+1]=row
  end
end
return rows
end)()
local function nativeKey(r)return table.concat({r.game,r.style,r.tileset,r.map or '',r.id,r.quadrant,r.x or '',r.y or ''},':')end
local nativeIndex={}for i,r in ipairs(rows)do nativeIndex[nativeKey(r)]=i end
for _,r in ipairs(nativeUpdates)do local i=assert(nativeIndex[nativeKey(r)],'Missing native Route32/Union source key');assert(rows[i].sourceHash==r.sourceHash);rows[i]=r end
-- END NATIVE CRYSTALDUST ROUTE32 UNION
return rows
